// TTL adjustment for caching endpoints - JIRA-4829
// Increase TTL to 600 seconds for /api/v1/data and /api/v2/data endpoints
pipeline {
    agent any
    stages {
        stage('Update Cache Configuration') {
            steps {
                script {
                    // Update Redis TTL configuration
                    def cacheConfig = [
                        '/api/v1/data': 600,
                        '/api/v2/data': 600
                    ]
                    // Apply cache TTL settings
                    cacheConfig.each { endpoint, ttl ->
                        println "Setting TTL for ${endpoint} to ${ttl} seconds"
                        // Update Jenkins pipeline cache configuration
                        updateCacheTTL(endpoint, ttl)
                    }
                }
            }
        }
    }
}

